import java.util.*;

class Solution {
  public int[] recoverArray(int n, int[] sums) {
    List<Integer> list = new ArrayList<>();
    for (int x : sums) list.add(x);
    Collections.sort(list);
    return recover(n, list);
  }

  private int[] recover(int n, List<Integer> sums) {
    if (n == 0) return new int[0];
    int d = sums.get(1) - sums.get(0);
    Map<Integer, Integer> count = new HashMap<>();
    for (int x : sums) count.put(x, count.getOrDefault(x, 0) + 1);
    List<Integer> with = new ArrayList<>(), without = new ArrayList<>();
    for (int x : sums) {
      if (count.getOrDefault(x, 0) == 0) continue;
      without.add(x);
      count.put(x, count.get(x) - 1);
      int y = x + d;
      with.add(y);
      count.put(y, count.getOrDefault(y, 0) - 1);
    }
    if (without.contains(0)) {
      int[] r = recover(n - 1, without);
      int[] ans = Arrays.copyOf(r, n);
      ans[n - 1] = d;
      return ans;
    }
    int[] r = recover(n - 1, with);
    int[] ans = Arrays.copyOf(r, n);
    ans[n - 1] = -d;
    return ans;
  }
}
